<script setup>
import { onMounted, reactive, ref } from 'vue'
import { api, errorMessage } from './api'
const rows=ref([]), page=ref(1), last=ref(1), filter=ref('pending'), error=ref(''), busy=ref(false), notes=reactive({})
async function load(){busy.value=true;error.value='';try{const {data}=await api.get('/api/admin/leaves',{params:{page:page.value,status:filter.value}});rows.value=data.data;last.value=data.last_page}catch(err){error.value=errorMessage(err)}finally{busy.value=false}}
async function review(item,status){busy.value=true;error.value='';try{await api.patch(`/api/admin/leaves/${item.id}`,{status,review_note:notes[item.id] || ''});delete notes[item.id];await load()}catch(err){error.value=errorMessage(err)}finally{busy.value=false}}
onMounted(load)
</script>
<template><section><div class="filter-bar"><label>Request status<select v-model="filter" @change="page=1;load()"><option value="pending">Pending</option><option value="approved">Approved</option><option value="rejected">Rejected</option><option value="cancelled">Cancelled</option><option value="">All requests</option></select></label><button :disabled="busy" @click="load">Refresh</button></div><p v-if="error" class="notice danger" role="alert">{{error}}</p><div class="card table-card"><div class="table-scroll"><table><thead><tr><th>Employee</th><th>Dates / type</th><th>Reason</th><th>Decision</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td><strong>{{item.name}}</strong><small>{{item.email}}</small></td><td>{{item.start_date}} → {{item.end_date}}<small>{{item.type}} · {{item.status}}</small></td><td style="max-width:300px;white-space:pre-wrap;overflow-wrap:anywhere">{{item.reason}}</td><td><template v-if="item.status==='pending'"><label :for="'note-'+item.id">Review note</label><textarea :id="'note-'+item.id" v-model="notes[item.id]" maxlength="2000" rows="2"></textarea><div class="inline-actions" style="margin-top:10px"><button class="small-button primary" :disabled="busy" @click="review(item,'approved')">Approve</button><button class="small-button" :disabled="busy" @click="review(item,'rejected')">Reject</button></div></template><span v-else>{{item.review_note || '—'}}</span></td></tr><tr v-if="!rows.length"><td colspan="4" class="empty-cell">{{busy?'Loading requests…':'No matching leave requests.'}}</td></tr></tbody></table></div></div><div class="pagination"><span>Page {{page}} of {{last}}</span><div><button :disabled="busy || page<=1" @click="page--;load()">Previous</button><button :disabled="busy || page>=last" @click="page++;load()">Next</button></div></div></section></template>
